// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Milestone 4 (three-tier parity ExecPlan): an INNER {@code JoinCursor} whose right side is a correlated
 * non-flattenable fragment (here a MINUS group, one of the few shapes the optimizers leave as
 * {@code Join(Pattern, fragment)}) must, when the left-side row estimate justifies it and
 * {@code rdf4j.lmdb.leftjoin.sweep.enabled=true}, be answered by ONE key-unbound sweep of the fragment instead of one
 * fragment execution per outer row — the inner twin of {@code LmdbNativeLeftJoinSweepTest}.
 */
class LmdbNativeInnerJoinSweepTest {

	private static final String EX = "http://example.com/innersweep/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String SWEEP_FLAG = LmdbNativeAggregateCompiler.LEFTJOIN_SWEEP_ENABLED;

	private static final String QUERY = "SELECT ?outer ?leaf WHERE { ?outer <" + EX + "seed> ?seed . { ?seed <" + EX
			+ "inner> ?leaf . MINUS { ?seed <" + EX + "alt> ?leaf . } } }";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI seed = vf.createIRI(EX, "seed");
			IRI inner = vf.createIRI(EX, "inner");
			IRI alt = vf.createIRI(EX, "alt");
			for (int i = 0; i < 200; i++) {
				IRI outer = vf.createIRI(EX, "outer" + i);
				IRI seedNode = vf.createIRI(EX, "seedNode" + i);
				conn.add(outer, seed, seedNode);
				// Outers 0..179 have one fragment row; the MINUS arm removes 60..119; 180..199 match nothing
				// and drop (inner join).
				if (i < 180) {
					IRI leaf = vf.createIRI(EX, "leaf" + i);
					conn.add(seedNode, inner, leaf);
					if (i >= 60 && i < 120) {
						conn.add(seedNode, alt, leaf);
					}
				}
			}
			// Duplicate outer edge: outer0 carries a second seed binding to seedNode1 — bag multiplicity.
			conn.add(vf.createIRI(EX, "outer0"), seed, vf.createIRI(EX, "seedNode1"));
		}
		System.setProperty(NATIVE_FLAG, "true");
	}

	@AfterEach
	void tearDown() {
		System.clearProperty(NATIVE_FLAG);
		System.clearProperty(SWEEP_FLAG);
		repository.shutDown();
	}

	@Test
	void estimateJustifiedCorrelatedInnerFragmentIsServedByOneSweep() {
		List<String> expected = rows(QUERY);
		assertThat(expected).hasSize(120 + 1); // 180 fragment rows minus 60 removed, plus outer0's second seed

		System.setProperty(SWEEP_FLAG, "true");
		long sweepsBefore = LmdbNativeAggregateCompiler.LEFTJOIN_SWEEP_BUILDS.get();
		List<String> actual = rows(QUERY);

		assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(LmdbNativeAggregateCompiler.LEFTJOIN_SWEEP_BUILDS.get() - sweepsBefore)
				.as("the correlated inner fragment must be swept exactly once for the whole outer stream")
				.isOne();
	}

	@Test
	void flagOffKeepsPerRowEvaluationUntouched() {
		long sweepsBefore = LmdbNativeAggregateCompiler.LEFTJOIN_SWEEP_BUILDS.get();
		List<String> rows = rows(QUERY);
		assertThat(rows).hasSize(121);
		assertThat(LmdbNativeAggregateCompiler.LEFTJOIN_SWEEP_BUILDS.get() - sweepsBefore).isZero();
	}

	private List<String> rows(String query) {
		List<String> rows = new ArrayList<>();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			try (var result = conn.prepareTupleQuery(query).evaluate()) {
				while (result.hasNext()) {
					BindingSet bindings = result.next();
					List<String> parts = new ArrayList<>();
					for (String name : bindings.getBindingNames()) {
						parts.add(name + "=" + bindings.getValue(name));
					}
					parts.sort(String::compareTo);
					rows.add(String.join("|", parts));
				}
			}
		}
		return rows;
	}
}
